_GROUPED = re.compile(r"^\d{1,3}(?:,\d{3})+$")


def _strip_separators(raw: str) -> str:
    """Drop thousands separators, but only from well-formed grouped digits.

    Anything else (``1,2,3``, ``1,``, ``1,234.5,6``) is left untouched so the
    numeric conversion raises ``ValueError`` as it always did. Only commas are
    stripped -- a non-breaking space is far more likely to be a typo, and
    swallowing it silently would hide real row corruption.
